#include <iostream>
#include <string>
#include <stack>
using namespace std;

class SolutionStack {
    /** 2390. Removing Stars From a String
     * https://leetcode.com/problems/removing-stars-from-a-string/
     */
public:
    string removeStars(string s) {
        stack<char> S;
        for (const char& c: s) {
            if ('*' == c) {
                S.pop();
            } else {
                S.push(c);
            }
        }
        string res;
        while (!S.empty()) {
            res = S.top() + res;
            S.pop();
        }
        return res;
    }
};

class Solution {
    /** 2390. Removing Stars From a String
     * https://leetcode.com/problems/removing-stars-from-a-string/
     */
public:
    string removeStars(string s) {
        size_t ic = 0; // count of char
        size_t is = 0; // star position
        while (is != s.size() && '*' != s[is]) {
            ++ic; ++is;
        }
        if (is != s.size()) --ic;
        while (++is < s.size()) {
            if ('*' == s[is]) {
                --ic;
            } else {
                swap(s[ic++], s[is]);
            }
        }
        return s.substr(0, ic);
    }
};

int main(void)
{
	// string s = ""; // ""
	// string s = "erase*****"; // ""
	string s = "leet**cod*e"; // lecoe
	
	Solution solution;
	cout << solution.removeStars(s) << endl;
}
